#!/usr/bin/env python3
"""protein/mutation_effect_scan — auto-generated run.py (archetype=mutation_scan).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mutation_scan"
BRAIN = "protein"
SKILL = "mutation_effect_scan"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'mutation_effect_scan', 'wt_score': 0.0, 'scan_csv': '', 'top_mutations': [{'position': 1, 'from_aa': 'A', 'to_aa': 'V', 'ddg': 0.0}], 'diagnostics': {'brain': 'protein', 'archetype': 'mutation_scan'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """ESM-2 PLM mutation effect:逐位置/给定突变,计算 logit ratio (mutant - WT)。
    host_env=praxis-protein 或 esmfold(都有 fair-esm 2.0.0)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("sequence") or payload.get("wt_sequence")
    mutations = payload.get("mutations") or []  # e.g. ["A30V", "L67F"]
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="esm_mut_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "ESM-2", "n_mutations": len(mutations), "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
                "top_mutations": [], "diagnostics": {**diagnostics, "dry": True}}
    if not seq:
        return {"ok": False, "error": "需要 sequence (WT 序列)", "diagnostics": diagnostics}
    script = (
        "import json, sys, os, torch\n"
        "import esm\n"
        f"seq = {seq!r}; mutations = {mutations!r}; out_dir = {out_dir!r}\n"
        "os.makedirs(out_dir, exist_ok=True)\n"
        "model, alphabet = esm.pretrained.esm2_t33_650M_UR50D()\n"
        "model = model.eval()\n"
        "if torch.cuda.is_available(): model = model.cuda()\n"
        "bc = alphabet.get_batch_converter()\n"
        "_, _, tokens = bc([('wt', seq)])\n"
        "if torch.cuda.is_available(): tokens = tokens.cuda()\n"
        "with torch.no_grad():\n"
        "    logits = model(tokens)['logits'][0]  # L+2, vocab\n"
        "results = []\n"
        "for m in mutations:\n"
        "    if len(m) < 3:\n"
        "        results.append({'mutation': m, 'error': 'invalid'}); continue\n"
        "    wt_aa = m[0]; pos = int(m[1:-1]); mut_aa = m[-1]\n"
        "    if pos < 1 or pos > len(seq):\n"
        "        results.append({'mutation': m, 'error': 'out_of_range'}); continue\n"
        "    if seq[pos-1] != wt_aa:\n"
        "        results.append({'mutation': m, 'error': f'WT mismatch (expected {wt_aa}, got {seq[pos-1]})'}); continue\n"
        "    wt_tok = alphabet.tok_to_idx[wt_aa]\n"
        "    mut_tok = alphabet.tok_to_idx[mut_aa]\n"
        "    delta = float(logits[pos, mut_tok] - logits[pos, wt_tok])\n"
        "    results.append({'mutation': m, 'position': pos, 'from_aa': wt_aa, 'to_aa': mut_aa, 'ddg': -delta})\n"
        "import csv\n"
        "csv_path = os.path.join(out_dir, 'scan.csv')\n"
        "with open(csv_path, 'w') as fh:\n"
        "    w = csv.DictWriter(fh, fieldnames=['mutation','position','from_aa','to_aa','ddg','error'])\n"
        "    w.writeheader()\n"
        "    for r in results: w.writerow({**{'error':''}, **r})\n"
        "valid = [r for r in results if 'ddg' in r]\n"
        "valid.sort(key=lambda x: x['ddg'])\n"
        "json.dump({'scan_csv': csv_path, 'top_mutations': valid[:10], 'wt_score': 0.0,\n"
        "           'all_results': results}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "ESM mutation scan 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, "wt_score": parsed.get("wt_score", 0.0),
            "scan_csv": parsed.get("scan_csv", ""), "top_mutations": parsed.get("top_mutations", []),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "all_results": parsed.get("all_results")}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
